/// Case-insensitive Unicode name lookup (mirrors `unicodedata.lookup`
/// for primary names; CJK Unified Ideographs resolve algorithmically).
pub fn unicode_name_lookup(name: &str) -> Option<char> {
    let upper = name.to_uppercase();
    if let Some(hex) = upper.strip_prefix("CJK UNIFIED IDEOGRAPH-") {
        return u32::from_str_radix(hex, 16).ok().and_then(char::from_u32);
    }
    UNICODE_NAMES
        .binary_search_by(|(n, _)| n.cmp(&upper.as_str()))
        .ok()
        .map(|i| UNICODE_NAMES[i].1)
}
